import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZRound39BridgeCallerOracle extends GhidraScript{
 static final long RET=0x12345000L,MIX=0x12346000L,S=0x7fff0000L,R=0x6151e0L,E=0x5c9a88L;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(i*8);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}long mix(long h,long n){return((h^(n&0xffffffffL))*16777619L)&0xffffffffL;}long hash(byte[]b){long h=2166136261L;for(byte v:b)h=mix(h,v&255);return h;}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<256;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(R),new byte[12*32]);for(int i=0;i<12;i++)put(e,R+i*32,2,-1);put(e,R,2,320);put(e,R+2,2,320);put(e,R+4,2,96);put(e,R+6,2,48);put(e,R+8,2,new int[]{0,1,100,200}[s/2%4]);put(e,R+10,2,200);put(e,R+12,2,s%2);put(e,R+15,1,s/128%2==0?0:32);int strength=new int[]{0,1,100,201}[s/8%4];e.writeMemory(toAddr(0x58aaaa),new byte[16384]);for(int y=19;y<=23;y++)for(int x=19;x<=26;x++)put(e,0x58aaaa+y*128+x,1,135);e.writeMemory(toAddr(0x5b6da4),new byte[96*136]);for(int i=0;i<4;i++)put(e,0x5b6da4+i*2,2,new int[]{320,320,416,368}[i]);e.writeMemory(toAddr(0x615360),new byte[12*16]);put(e,0x4a651b,1,0);e.writeMemory(toAddr(E),new byte[500*44]);int free=new int[]{0,1,7,500}[s/32%4];for(int i=0;i<500;i++)put(e,E+i*44,2,i<free?-1000:100);put(e,0x622e1c,4,500);put(e,0x4d18fa,1,1);put(e,0x4a67fc,4,100);put(e,0x4d0288,2,1234);put(e,0x4a6e72,1,1);put(e,0x4d18ee,1,s%2);put(e,0x4a6e6f,1,1);put(e,0x4a6f4e,1,s%8);put(e,0x6323a0,1,1);put(e,0x622cb8,2,s/64%2==0?0:1200);put(e,0x622cba,2,0);put(e,0x498c24,2,640);put(e,0x498c20,2,480);put(e,0x681588,2,s*17);long table=Integer.toUnsignedLong(getInt(toAddr(0x4a0dac)));put(e,0x6815a0,4,table);put(e,0x680d08,2,120);for(int i=0;i<1024;i++){if(getShort(toAddr(table+i*44+2))==-1)break;put(e,table+i*44+28,2,0);}put(e,0x474214,4,MIX);e.writeMemory(toAddr(0x595b12),new byte[500]);long blast=hash(e.readMemory(toAddr(0x595b12),500));long[]pcs={RET,MIX,0x409a60,0x409870,0x41f870,0x459d10,0x43f650,0x4094e0,0x409690,0x460910};for(long pc:pcs)e.setBreakpoint(toAddr(pc));e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,2580);e.writeRegister("ECX",0);e.writeRegister("EDX",strength);if(!e.run(toAddr(0x409c50),null,monitor))throw new Exception(e.getLastError());long trace=2166136261L;String order="";int draws=0,sound=0,atSound=-1,atTerrain=-1;int count=0;while(e.readRegister("EIP").longValue()!=RET){if(++count>1000)throw new Exception("eventbudget");long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();trace=mix(trace,pc);if(pc==0x460910){e.writeRegister("EAX",s*2027^draws*7919^0x7731a5c9);draws++;long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());continue;}
 if(pc==MIX){sound++;order+="S";e.writeRegister("EAX",3);}else if(pc==0x459d10)order+="U";else if(pc==0x43f650)order+="O";else{if(pc==0x409a60||pc==0x409870)order+="F";if(pc==0x41f870){order+="B";atSound=draws;}if(pc==0x4094e0){order+="T";atTerrain=draws;}if(pc==0x409690)order+="D";trace=mix(trace,e.readRegister("ECX").longValue());trace=mix(trace,e.readRegister("EDX").longValue());if(!e.step(monitor))throw new Exception(e.getLastError());if(!e.run(toAddr(e.readRegister("EIP").longValue()),null,monitor))throw new Exception(e.getLastError());continue;}long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 int active=0;for(int i=0;i<500;i++)if((short)read(e,E+i*44,2)!=-1000)active++;out.println("{\"scenario\":"+s+",\"hp\":"+(short)read(e,R+8,2)+",\"flags\":"+read(e,R+15,1)+",\"result\":"+(e.readRegister("EAX").intValue()&255)+",\"random\":"+draws+",\"atSound\":"+atSound+",\"atTerrain\":"+atTerrain+",\"sound\":"+sound+",\"cycle\":"+read(e,0x4a6f4e,1)+",\"gate\":"+read(e,0x4d18ee,1)+",\"effectCounter\":"+read(e,0x681588,2)+",\"active\":"+active+",\"phaseCounter\":"+read(e,0x4a67fc,4)+",\"suppress\":"+read(e,0x4d18fa,1)+",\"terrain\":"+hash(e.readMemory(toAddr(0x58aaaa),16384))+",\"pool\":"+hash(e.readMemory(toAddr(E),500*44))+",\"blastChanged\":"+(blast==hash(e.readMemory(toAddr(0x595b12),500))?0:1)+",\"trace\":"+trace+",\"order\":\""+order+"\"}");}finally{e.dispose();}}}}
}